import { ADD, Del } from "../types";

const initalState = {
  task: [],
};

const taskReducer = (state = initalState, action) => {
  switch (action.type) {
    case ADD:
      return {
        task: [
          ...state.task,
          { id: new Date().getTime(), task: action.payload, date: `${new Date().getFullYear()} / ${new Date().getMonth()} / `},
        ],
      };
    case Del:

    default:
      return state;
  }
};

export default taskReducer
